  'Music Theory IV',
  'A fourth-semester music theory course focused on post-tonal and twentieth-century techniques. Students analyze late Romantic harmony, extended and altered chords, impressionism, free atonality, twelve-tone technique, set theory, twentieth-century rhythm and meter, minimalism, introductory jazz harmony, and contemporary scores while connecting analysis to listening, performance, composition, notation, technology, and cultural context.',
  $mt4json${"slug": "music-theory-iv", "title": "Music Theory IV", "description": "A fourth-semester music theory course focused on post-tonal and twentieth-century techniques. Students analyze late Romantic harmony, extended and altered chords, impressionism, free atonality, twelve-tone technique, set theory, twentieth-century rhythm and meter, minimalism, introductory jazz harmony, and contemporary scores while connecting analysis to listening, performance, composition, notation, technology, and cultural context.", "topics": [{"id": "4e79d7e0-df24-429c-bb02-1940d0203925", "type": "topic", "title": "Late Romantic Harmony", "description": "Late Romantic harmony stretches tonal practice toward chromatic saturation, tonal ambiguity, and expanded expressive color.", "children": [{"id": "754d8dd4-16bd-4694-b0d2-e16f081e0b55", "type": "subtopic", "title": "Expanded chromaticism", "children": [{"id": "b8d5dd24-7078-4960-b30e-5c6a9f66ed73", "type": "concept", "title": "chromatic mediants"}, {"id": "13b05f4e-6b4d-41fd-928c-307420251fa7", "type": "concept", "title": "common-tone modulations"}, {"id": "5004439b-7aaf-4507-8717-2f64fe6d31b9", "type": "concept", "title": "third-related keys"}], "description": "Students study how chromatic harmony intensifies tonal direction and destabilizes key centers."}, {"id": "04de054c-1368-48ae-bfc6-280551ee5992", "type": "subtopic", "title": "Tonal ambiguity", "children": [{"id": "32587f6c-2da7-4bdf-9558-c4cad06717e7", "type": "concept", "title": "delayed resolution"}, {"id": "ccf36b33-88e9-44a6-8720-cd97b2bc7135", "type": "concept", "title": "prolonged dominant"}, {"id": "cc720353-6384-470e-8ce2-7c2c73fbf6c6", "type": "concept", "title": "ambiguous tonic"}], "description": "The class examines passages where tonal function is delayed, blurred, or multiply interpreted."}, {"id": "7b1ab9ee-6871-4dfc-be04-29ec2bf9f99a", "type": "subtopic", "title": "Repertoire context", "children": [{"id": "59082226-e4d6-4c81-839f-8c632714c25e", "type": "concept", "title": "Tristan-style chromaticism"}, {"id": "1eb93aaf-ccd6-45bc-9757-5017465a5405", "type": "concept", "title": "large-scale tension"}, {"id": "836293a1-1f3c-4190-85ac-3e3176be757b", "type": "concept", "title": "orchestral color"}], "description": "Students connect late Romantic harmonic language to Wagner, Mahler, Strauss, and related traditions."}]}, {"id": "ebb92ef6-f850-4665-b3b6-b4a38652d743", "type": "topic", "title": "Extended and Altered Chords", "description": "Extended and altered chords prepare students for late tonal, jazz-adjacent, and twentieth-century harmonic vocabularies.", "children": [{"id": "e1557492-35b5-4530-a6cc-d885a30ca4d0", "type": "subtopic", "title": "Extended tertian sonorities", "children": [{"id": "bef651bd-535f-4e40-97bd-bd885591d489", "type": "concept", "title": "dominant ninths"}, {"id": "7e8da3e4-bb12-4550-8a60-b224caa3061a", "type": "concept", "title": "added-sixth sonorities"}, {"id": "5351ab29-711d-4031-9a78-dc09f1c3af9f", "type": "concept", "title": "extended dominants"}], "description": "Students identify ninth, eleventh, and thirteenth chords in context."}, {"id": "720f9997-2ade-4d25-8796-110c19109af0", "type": "subtopic", "title": "Altered dominant harmony", "children": [{"id": "c32cb740-c9ce-47b1-b057-59661a3c16a4", "type": "concept", "title": "flat ninth"}, {"id": "aade17e9-fd20-4bc9-8bf6-66e4ab711e67", "type": "concept", "title": "sharp fifth"}, {"id": "9d112c50-cb2d-4805-8bb4-f9314395d6c5", "type": "concept", "title": "tritone substitution preview"}], "description": "The class studies chromatic alterations that reshape dominant function."}, {"id": "900b7508-8b7c-41e7-8a95-c409fee55697", "type": "subtopic", "title": "Voice-leading and sonority", "children": [{"id": "dc78a624-7f06-4bac-9a62-6d9532a11553", "type": "concept", "title": "tendency tones"}, {"id": "be9ab92b-3959-472c-9e2a-a7d69d185fe2", "type": "concept", "title": "smooth chromatic lines"}, {"id": "6ec5728d-c46a-4dd8-acd6-f7054806a7dd", "type": "concept", "title": "registral spacing"}], "description": "Students analyze how chord color and linear resolution interact."}]}, {"id": "bba23115-cfe7-428d-afbe-85d97290b4c4", "type": "topic", "title": "Impressionism (Debussy, Ravel)", "description": "This unit introduces coloristic harmony, modal resources, and texture as primary analytical concerns.", "children": [{"id": "cbac2138-1384-45a8-991d-4e73ada6bf56", "type": "subtopic", "title": "Modes and scales", "children": [{"id": "43aec1b7-6426-4e68-bf4d-094078425501", "type": "concept", "title": "whole-tone scale"}, {"id": "3a07fa4f-f54a-4e8d-a269-aaeb82fd36fb", "type": "concept", "title": "pentatonic scale"}, {"id": "2bf8f270-476e-4210-9ee9-e87a2a7050a6", "type": "concept", "title": "church modes"}], "description": "Students study alternatives to common-practice major/minor syntax."}, {"id": "4d6775cb-67b2-43ec-a4a2-ea8a8b0914ca", "type": "subtopic", "title": "Planing and parallelism", "children": [{"id": "06837691-9154-4657-acd2-33be4c6bf6c4", "type": "concept", "title": "parallel triads"}, {"id": "edf8858a-38f7-4b8a-9be5-67b34c6a6fc1", "type": "concept", "title": "parallel seventh chords"}, {"id": "4158aaec-1491-4140-94f3-ee3f825d42cd", "type": "concept", "title": "coloristic planing"}], "description": "The class analyzes parallel chord motion and nonfunctional sonority."}, {"id": "56181411-8dcf-40ab-9175-3e8bfdf4d24a", "type": "subtopic", "title": "Timbre and texture", "children": [{"id": "c1131209-d2c8-43e1-9c67-41497fe76872", "type": "concept", "title": "orchestral color"}, {"id": "031b099c-0448-4a9f-b93e-9e3dc8df68fd", "type": "concept", "title": "piano resonance"}, {"id": "093a0de7-7662-4836-9124-5bc05e2aa1e4", "type": "concept", "title": "textural layers"}], "description": "Students connect harmony to register, instrumentation, pedal, and resonance."}]}, {"id": "3d6c8325-c9a2-403c-bffa-d80898dc81f9", "type": "topic", "title": "Atonality and Free Atonality", "description": "Free atonality asks students to analyze music without assuming a tonal center or functional progression.", "children": [{"id": "8f0f74b8-c6a7-4f67-87b5-3331304bab6a", "type": "subtopic", "title": "Pitch organization without tonality", "children": [{"id": "448d7be0-8915-45cd-ae63-48a3f5c5d812", "type": "concept", "title": "interval cells"}, {"id": "873d8157-6e54-487e-bc5c-25b38e63770b", "type": "concept", "title": "motivic saturation"}, {"id": "7fa73591-7e10-4a1c-82df-8c8dce1e421e", "type": "concept", "title": "registral design"}], "description": "Students learn how composers create coherence through motives, intervals, and registers."}, {"id": "5e575dd6-ad74-4063-b240-1e4d68ca5cad", "type": "subtopic", "title": "Contour and gesture", "children": [{"id": "7961ba84-6cd2-4401-a8a9-52d9f204630a", "type": "concept", "title": "gestural analysis"}, {"id": "7e58d4ad-4ebc-4f17-8026-6c3c0e9f8720", "type": "concept", "title": "contour"}, {"id": "f842ef6f-9ecb-4ccb-ac8f-6721d00bcac3", "type": "concept", "title": "density"}], "description": "The class treats shape, attack, rhythm, and texture as structural features."}, {"id": "1614da30-b266-4f8a-b602-a5db6e7de8fa", "type": "subtopic", "title": "Analytical vocabulary", "children": [{"id": "9f389fea-131b-4411-b8dd-286b5b60abf8", "type": "concept", "title": "pitch-class language"}, {"id": "3fa30db0-053d-44b4-b5c8-20af1c276656", "type": "concept", "title": "interval vectors preview"}, {"id": "65f22167-6aae-459b-ae38-d9099dd8f34d", "type": "concept", "title": "segmentation"}], "description": "Students practice precise description for music that resists Roman-numeral analysis."}]}, {"id": "5ce85b67-c68b-4e69-8e5e-2bd15c3693cf", "type": "topic", "title": "Twelve-Tone Technique", "description": "Twelve-tone technique introduces a rigorous compositional system for organizing all twelve pitch classes.", "children": [{"id": "70f170d0-bac9-424a-a94d-87ac0a3f3ef2", "type": "subtopic", "title": "Tone rows", "children": [{"id": "3711d22c-1187-4554-871b-6212937c8921", "type": "concept", "title": "prime form"}, {"id": "618da9c3-d215-4344-bd9d-55ddeef87ace", "type": "concept", "title": "row ordering"}, {"id": "f3e5bbb8-4a42-40f5-a7bf-e4871780e01f", "type": "concept", "title": "aggregate"}], "description": "Students learn to identify and construct ordered pitch-class rows."}, {"id": "14cfd028-2b45-473f-8a27-1fdc8237fd7b", "type": "subtopic", "title": "Row operations", "children": [{"id": "f6247aae-bcbb-4a60-bcbd-40e16e4ecdc2", "type": "concept", "title": "inversion"}, {"id": "e70e0bd2-9eb6-4b12-85e7-fb9e2563ff10", "type": "concept", "title": "retrograde"}, {"id": "0d5cab5f-1124-4006-a8a3-201d54ea594b", "type": "concept", "title": "retrograde inversion"}], "description": "The unit covers the standard transformations used in serial composition."}, {"id": "404e79d6-1eba-4370-a040-a099905b0c8b", "type": "subtopic", "title": "Matrix and analysis", "children": [{"id": "824817bd-ee64-4b02-a5e3-406dc5dc5c71", "type": "concept", "title": "twelve-tone matrix"}, {"id": "0b2bc0f9-3f25-4c71-96b3-9485c4a67472", "type": "concept", "title": "row labels"}, {"id": "649d0683-959e-428d-b658-a3ee4c7e3ac4", "type": "concept", "title": "partitioning"}], "description": "Students build matrices and trace row forms through short works."}]}, {"id": "36c83826-effa-4de1-8fad-5a54acc5b574", "type": "topic", "title": "Set Theory Basics", "description": "Set theory gives students a compact language for comparing pitch collections in post-tonal music.", "children": [{"id": "421eecd4-1824-4862-9719-f720ce14aa34", "type": "subtopic", "title": "Pitch class and normal order", "children": [{"id": "96f4f80d-e7f4-453a-8c18-ae3c9f6eeb7f", "type": "concept", "title": "pitch-class integers"}, {"id": "cab33e59-1cb6-4a53-aa13-1303d2535428", "type": "concept", "title": "normal order"}, {"id": "b69faad5-bfe0-4abe-95a3-84ba60271d1a", "type": "concept", "title": "best normal order"}], "description": "Students learn the basic tools for unordered pitch-class collections."}, {"id": "e36ec5d8-e789-4325-a344-2aba197efa6f", "type": "subtopic", "title": "Prime form and interval class", "children": [{"id": "5d65bfe8-90d7-4011-b6bc-03083ddf277e", "type": "concept", "title": "prime form"}, {"id": "ff063b9d-5551-49e1-b1c8-f0f997c04142", "type": "concept", "title": "interval class"}, {"id": "63ca1aaa-c7e0-490b-8698-a0a1661997d0", "type": "concept", "title": "Tn/TnI equivalence"}], "description": "The class compares sets through transposition and inversion."}, {"id": "35b1a369-1304-4e9a-acff-78f8efccff88", "type": "subtopic", "title": "Set relationships", "children": [{"id": "21477fa0-4a75-48bb-bce8-301c8e4a30b4", "type": "concept", "title": "subset"}, {"id": "8f7f6562-5953-4055-858b-34b273637b86", "type": "concept", "title": "superset"}, {"id": "2583a5df-e26c-4607-bbd1-6b8eabf67f0b", "type": "concept", "title": "common-tone relationships"}], "description": "Students use set theory to explain motive, recurrence, and large-scale coherence."}]}, {"id": "4360cb40-b394-4ecb-9782-f7d54bc966ee", "type": "topic", "title": "Rhythm and Meter in the 20th Century", "description": "Modern rhythm expands the course beyond pitch, showing how time itself becomes a central compositional material.", "children": [{"id": "df5ede40-da83-46a8-8d03-ab3fce20d8ae", "type": "subtopic", "title": "Asymmetrical meter", "children": [{"id": "f6074ea0-10f0-4f33-a9d3-f377ed518eeb", "type": "concept", "title": "5/8"}, {"id": "3f0251de-c362-4879-9928-5e9de23576bc", "type": "concept", "title": "7/8"}, {"id": "e7dfbdf0-d2c1-4f33-ba18-a4fde41ccefa", "type": "concept", "title": "mixed meter"}], "description": "Students study changing and irregular meters."}, {"id": "05b0936a-c575-454b-bb32-70d40118baa8", "type": "subtopic", "title": "Polyrhythm and polymeter", "children": [{"id": "46bab4a1-76ab-49ef-9269-2f6d3f832311", "type": "concept", "title": "cross-rhythm"}, {"id": "7483d905-2b53-4070-8df1-313a8e71a2ba", "type": "concept", "title": "metric dissonance"}, {"id": "b5356a86-d2a5-425b-96a4-20cea3a205c4", "type": "concept", "title": "layered pulses"}], "description": "The class analyzes simultaneous rhythmic layers and metric conflicts."}, {"id": "c4c0443f-4b24-4dcc-9346-f3e9fe04fb87", "type": "subtopic", "title": "Rhythmic process", "children": [{"id": "1fd1101a-e2ae-4632-a138-4c487e8e48af", "type": "concept", "title": "additive rhythm"}, {"id": "c4c2ff1a-f686-402c-9cab-11057f24db58", "type": "concept", "title": "augmentation/diminution"}, {"id": "c783c183-5d5f-466e-935c-2c40951545fe", "type": "concept", "title": "phasing preview"}], "description": "Students connect rhythm to form, texture, and perception."}]}, {"id": "042270e5-df13-4666-b3b0-d346e73951c0", "type": "topic", "title": "Minimalism", "description": "Minimalism introduces process, repetition, gradual change, and perceptual listening as analytical foundations.", "children": [{"id": "561fea12-7b3c-4c3a-9f49-31451cd8bf21", "type": "subtopic", "title": "Process and repetition", "children": [{"id": "1e85c022-7567-4ff3-b9d7-a3cd93c13f15", "type": "concept", "title": "ostinato"}, {"id": "5924a36a-3a55-4f02-80e0-114eced080ba", "type": "concept", "title": "looping"}, {"id": "1fc4ec79-be5f-4dec-a752-8cec810fd5ea", "type": "concept", "title": "gradual process"}], "description": "Students analyze how repeated patterns become form."}, {"id": "acbed846-f269-40fe-87e6-db64b6a89076", "type": "subtopic", "title": "Phasing and additive techniques", "children": [{"id": "7ee29b10-af98-46fb-9376-56617babd338", "type": "concept", "title": "phase shifting"}, {"id": "e6510c3d-701e-4478-9565-7338edf1a60f", "type": "concept", "title": "additive process"}, {"id": "3410ff73-2a4e-4343-852f-877ca72d9dee", "type": "concept", "title": "subtractive process"}], "description": "The class studies canonical minimalist procedures."}, {"id": "8fee2f6d-eb46-453f-8129-a4416589d825", "type": "subtopic", "title": "Listening and perception", "children": [{"id": "aa2a722e-8289-4045-b235-9be14e60b718", "type": "concept", "title": "pattern recognition"}, {"id": "941aa882-ea88-4215-b186-2bc715894879", "type": "concept", "title": "surface change"}, {"id": "d9e1dae0-eb9d-4ba5-a4d4-e3c41c68502e", "type": "concept", "title": "large-scale stasis"}], "description": "Students examine how small changes alter attention and musical time."}]}, {"id": "0f05ff40-3499-40a6-af63-149d65edb725", "type": "topic", "title": "Introduction to Jazz Harmony", "description": "This unit gives non-jazz and classical-track students a practical bridge into chord symbols, extensions, and harmonic syntax.", "children": [{"id": "4c304a48-68e4-411f-9898-dd54c464a730", "type": "subtopic", "title": "Chord symbols and extensions", "children": [{"id": "e78b19da-ba75-424e-bbea-56a9a7a3f17e", "type": "concept", "title": "maj7"}, {"id": "01c49e4d-27cb-4552-bb8a-5d6f73b1223e", "type": "concept", "title": "min7"}, {"id": "708bd3d3-d8f6-4d1e-b8e4-8066dad7f27d", "type": "concept", "title": "dominant 7/9/13"}], "description": "Students learn basic jazz-symbol reading and common extended sonorities."}, {"id": "3226247a-9095-4a6e-b55b-74e585d8112f", "type": "subtopic", "title": "ii-V-I and turnaround syntax", "children": [{"id": "755385c0-5bea-47d4-9de5-3ff7b7941b23", "type": "concept", "title": "ii-V-I"}, {"id": "94494782-ed38-46bc-b84d-d229a3a11f70", "type": "concept", "title": "turnaround"}, {"id": "71d01c12-4cb2-486f-a8be-f3f790edec56", "type": "concept", "title": "circle progressions"}], "description": "The class studies the most common jazz harmonic patterns."}, {"id": "a28cc4a3-91b3-4cea-a886-59151db39c0a", "type": "subtopic", "title": "Modal and blues resources", "children": [{"id": "46e4d965-1f0c-43a1-885c-94f6d717e11b", "type": "concept", "title": "blues scale"}, {"id": "fbb02942-a406-4904-b5bd-733d1ae35078", "type": "concept", "title": "Dorian mode"}, {"id": "7132ac4a-55c8-400e-bea1-3a91159779b6", "type": "concept", "title": "modal vamp"}], "description": "Students connect jazz harmony to modes, blues forms, and improvisational thinking."}]}, {"id": "ce53cc58-c969-4b74-a596-f0709c43aa3c", "type": "topic", "title": "Analysis of Contemporary Scores", "description": "Students synthesize twentieth- and twenty-first-century tools by analyzing scores that combine pitch, rhythm, timbre, form, and context.", "children": [{"id": "7d9cd90b-f6bb-46ab-9252-4674eff8ce8b", "type": "subtopic", "title": "Score annotation strategy", "children": [{"id": "e73c7574-5f6f-4dda-b12a-7069e98c3580", "type": "concept", "title": "pitch organization"}, {"id": "c1d57faf-2c75-4ad3-a49f-fec806f6b534", "type": "concept", "title": "rhythmic process"}, {"id": "be3aae83-5490-49a9-828f-54365691c990", "type": "concept", "title": "texture and timbre"}], "description": "Students learn how to mark contemporary scores with layered analytical observations."}, {"id": "ed63399a-1a07-46f0-83f4-ecf82a7d80a9", "type": "subtopic", "title": "Technology and notation", "children": [{"id": "4eccb2fe-cde4-48a8-b8d8-be94d77892d2", "type": "concept", "title": "graphic notation"}, {"id": "9e8f0fe2-a9d6-44f8-a52f-a2139ca217a6", "type": "concept", "title": "extended techniques"}, {"id": "1859f52e-1a5f-4bfd-80c3-83cdadfbe2a6", "type": "concept", "title": "fixed media/electronics"}], "description": "The class considers contemporary notation, electronics, and performance instructions."}, {"id": "d0e252fe-f6bc-4043-8487-137353174cc5", "type": "subtopic", "title": "Interpretive argument", "children": [{"id": "2b181b8c-fa4f-459e-aece-2e641e613c66", "type": "concept", "title": "analytical thesis"}, {"id": "777aef1d-3e83-4c4a-b3f5-3d4d3eb40c42", "type": "concept", "title": "listening evidence"}, {"id": "dd824d28-8ee1-4800-a978-e7796e152eec", "type": "concept", "title": "performance implications"}], "description": "Students write concise analytical claims supported by score, sound, and context."}]}, {"id": "c25be5a2-e563-4237-9172-1d4f64815478", "type": "topic", "title": "Listening, Performance, and Composition Lab", "description": "This added world-class unit keeps advanced theory grounded in sound, embodiment, and creative practice.", "children": [{"id": "4d79a581-c646-4a37-b8b7-f7039a46e139", "type": "subtopic", "title": "Listening lab", "children": [{"id": "1cffbef7-6afa-4ad0-a4e5-dcf64f440705", "type": "concept", "title": "mode/color hearing"}, {"id": "544d82ec-bd3a-4e81-a54b-20d92401cfb7", "type": "concept", "title": "row recognition"}, {"id": "60647c1a-453b-4ce5-93f4-5f7eb67a5930", "type": "concept", "title": "process listening"}], "description": "Students identify post-tonal techniques by ear and describe their perceptual effect."}, {"id": "b6db4d91-86bc-43c7-abef-e7248488a910", "type": "subtopic", "title": "Performance application", "children": [{"id": "af3b29ca-7036-4347-9c59-a136c5880110", "type": "concept", "title": "cueing rhythm"}, {"id": "6ef41c52-c2d6-4636-afe3-6f8537dd989d", "type": "concept", "title": "intonation in dissonance"}, {"id": "16aa05f5-54c7-4856-9bfe-ccc60ce0b97c", "type": "concept", "title": "texture balance"}], "description": "Students connect analysis to rehearsal decisions, timing, articulation, and interpretation."}, {"id": "79494272-1152-4703-93f2-ea871af6fe33", "type": "subtopic", "title": "Composition etudes", "children": [{"id": "d5fac9d0-ee1f-4110-9e8f-5468af599826", "type": "concept", "title": "whole-tone miniature"}, {"id": "e52236c7-ccc8-4680-b2ac-e6e55bc06d51", "type": "concept", "title": "set-class etude"}, {"id": "3b06a061-d30d-4241-bb5a-a052edb04812", "type": "concept", "title": "minimalist process study"}], "description": "Students write short studies using the techniques they analyze."}]}, {"id": "59267f32-a6e1-4907-8061-a4b30232e909", "type": "topic", "title": "Analytical Methods and Context", "description": "This added capstone helps students choose the right analytical method for the music instead of forcing every piece into one system.", "children": [{"id": "cbe1cc9e-d8d2-4de1-9a02-b2e21a995fa0", "type": "subtopic", "title": "Method selection", "children": [{"id": "89aeb6c5-ef67-40dc-a4b2-de82c65ea6e1", "type": "concept", "title": "tool choice"}, {"id": "143b465a-5740-406d-bb3c-73d695faf0e6", "type": "concept", "title": "limits of method"}, {"id": "2967fbc8-efed-42e1-b851-a02f52a939e3", "type": "concept", "title": "mixed-method analysis"}], "description": "Students compare tonal, set-theoretic, rhythmic, formal, timbral, and cultural approaches."}, {"id": "05dc8f46-f1e4-436b-9dc0-f4e0d05fa4fd", "type": "subtopic", "title": "Historical and cultural framing", "children": [{"id": "6bbb851c-4764-4ab8-9f17-d43674e8491d", "type": "concept", "title": "modernism"}, {"id": "c5268851-85a0-42cc-b6d2-a52502a37218", "type": "concept", "title": "postmodernism"}, {"id": "79a58fd7-c941-4591-89fb-92195771d383", "type": "concept", "title": "global influence"}], "description": "The class connects technique to aesthetic movements, institutions, technology, and identity."}, {"id": "a9b31907-f9db-4183-a0f7-0fdef35dabd8", "type": "subtopic", "title": "Final portfolio synthesis", "children": [{"id": "baf3b019-b416-45e5-abaf-00012b17feb5", "type": "concept", "title": "annotated score"}, {"id": "9dc86a83-cf1f-417c-9cc9-9141f9425986", "type": "concept", "title": "short essay"}, {"id": "22eb7650-8ae7-4060-9e3b-b3042585f0b3", "type": "concept", "title": "creative artifact"}], "description": "Students present analysis, listening, and creative work as a coherent advanced-theory portfolio."}]}], "dbBacked": true}$mt4json$::jsonb,
