set
  title = 'Music Theory IV',
  goal = 'Music Theory IV',
  summary = 'A fourth-semester music theory course focused on post-tonal and twentieth-century techniques. Students analyze late Romantic harmony, extended and altered chords, impressionism, free atonality, twelve-tone technique, set theory, twentieth-century rhythm and meter, minimalism, introductory jazz harmony, and contemporary scores while connecting analysis to listening, performance, composition, notation, technology, and cultural context.',
  data = $mt4json${"slug": "music-theory-iv", "title": "Music Theory IV", "description": "A fourth-semester music theory course focused on post-tonal and twentieth-century techniques. Students analyze late Romantic harmony, extended and altered chords, impressionism, free atonality, twelve-tone technique, set theory, twentieth-century rhythm and meter, minimalism, introductory jazz harmony, and contemporary scores while connecting analysis to listening, performance, composition, notation, technology, and cultural context.", "topics": [{"id": "4e79d7e0-df24-429c-bb02-1940d0203925", "type": "topic", "title": "Late Romantic Harmony", "description": "Late Romantic harmony stretches tonal practice toward chromatic saturation, tonal ambiguity, and expanded expressive color.", "children": [{"id": "754d8dd4-16bd-4694-b0d2-e16f081e0b55", "type": "subtopic", "title": "Expanded chromaticism", "children": [{"id": "b8d5dd24-7078-4960-b30e-5c6a9f66ed73", "type": "concept", "title": "chromatic mediants"}, {"id": "13b05f4e-6b4d-41fd-928c-307420251fa7", "type": "concept", "title": "common-tone modulations"}, {"id": "5004439b-7aaf-4507-8717-2f64fe6d31b9", "type": "concept", "title": "third-related keys"}], "description": "Students study how chromatic harmony intensifies tonal direction and destabilizes key centers."}, {"id": "04de054c-1368-48ae-bfc6-280551ee5992", "type": "subtopic", "title": "Tonal ambiguity", "children": [{"id": "32587f6c-2da7-4bdf-9558-c4cad06717e7", "type": "concept", "title": "delayed resolution"}, {"id": "ccf36b33-88e9-44a6-8720-cd97b2bc7135", "type": "concept", "title": "prolonged dominant"}, {"id": "cc720353-6384-470e-8ce2-7c2c73fbf6c6", "type": "concept", "title": "ambiguous tonic"}], "description": "The class examines passages where tonal function is delayed, blurred, or multiply interpreted."}, {"id": "7b1ab9ee-6871-4dfc-be04-29ec2bf9f99a", "type": "subtopic", "title": "Repertoire context", "children": [{"id": "59082226-e4d6-4c81-839f-8c632714c25e", "type": "concept", "title": "Tristan-style chromaticism"}, {"id": "1eb93aaf-ccd6-45bc-9757-5017465a5405", "type": "concept", "title": "large-scale tension"}, {"id": "836293a1-1f3c-4190-85ac-3e3176be757b", "type": "concept", "title": "orchestral color"}], "description": "Students connect late Romantic harmonic language to Wagner, Mahler, Strauss, and related traditions."}]}, {"id": "ebb92ef6-f850-4665-b3b6-b4a38652d743", "type": "topic", "title": "Extended and Altered Chords", "description": "Extended and altered chords prepare students for late tonal, jazz-adjacent, and twentieth-century harmonic vocabularies.", "children": [{"id": "e1557492-35b5-4530-a6cc-d885a30ca4d0", "type": "subtopic", "title": "Extended tertian sonorities", "children": [{"id": "bef651bd-535f-4e40-97bd-bd885591d489", "type": "concept", "title": "dominant ninths"}, {"id": "7e8da3e4-bb12-4550-8a60-b224caa3061a", "type": "concept", "title": "added-sixth sonorities"}, {"id": "5351ab29-711d-4031-9a78-dc09f1c3af9f", "type": "concept", "title": "extended dominants"}], "description": "Students identify ninth, eleventh, and thirteenth chords in context."}, {"id": "720f9997-2ade-4d25-8796-110c19109af0", "type": "subtopic", "title": "Altered dominant harmony", "children": [{"id": "c32cb740-c9ce-47b1-b057-59661a3c16a4", "type": "concept", "title": "flat ninth"}, {"id": "aade17e9-fd20-4bc9-8bf6-66e4ab711e67", "type": "concept", "title": "sharp fifth"}, {"id": "9d112c50-cb2d-4805-8bb4-f9314395d6c5", "type": "concept", "title": "tritone substitution preview"}], "description": "The class studies chromatic alterations that reshape dominant function."}, {"id": "900b7508-8b7c-41e7-8a95-c409fee55697", "type": "subtopic", "title": "Voice-leading and sonority", "children": [{"id": "dc78a624-7f06-4bac-9a62-6d9532a11553", "type": "concept", "title": "tendency tones"}, {"id": "be9ab92b-3959-472c-9e2a-a7d69d185fe2", "type": "concept", "title": "smooth chromatic lines"}, {"id": "6ec5728d-c46a-4dd8-acd6-f7054806a7dd", "type": "concept", "title": "registral spacing"}], "description": "Students analyze how chord color and linear resolution interact."}]}, {"id": "bba23115-cfe7-428d-afbe-85d97290b4c4", "type": "topic", "title": "Impressionism (Debussy, Ravel)", "description": "This unit introduces coloristic harmony, modal resources, and texture as primary analytical concerns.", "children": [{"id": "cbac2138-1384-45a8-991d-4e73ada6bf56", "type": "subtopic", "title": "Modes and scales", "children": [{"id": "43aec1b7-6426-4e68-bf4d-094078425501", "type": "concept", "title": "whole-tone scale"}, {"id": "3a07fa4f-f54a-4e8d-a269-aaeb82fd36fb", "type": "concept", "title": "pentatonic scale"}, {"id": "2bf8f270-476e-4210-9ee9-e87a2a7050a6", "type": "concept", "title": "church modes"}], "description": "Students study alternatives to common-practice major/minor syntax."}, {"id": "4d6775cb-67b2-43ec-a4a2-ea8a8b0914ca", "type": "subtopic", "title": "Planing and parallelism", "children": [{"id": "06837691-9154-4657-acd2-33be4c6bf6c4", "type": "concept", "title": "parallel triads"}, {"id": "edf8858a-38f7-4b8a-9be5-67b34c6a6fc1", "type": "concept", "title": "parallel seventh chords"}, {"id": "4158aaec-1491-4140-94f3-ee3f825d42cd", "type": "concept", "title": "coloristic planing"}], "description": "The class analyzes parallel chord motion and nonfunctional sonority."}, {"id": "56181411-8dcf-40ab-9175-3e8bfdf4d24a", "type": "subtopic", "title": "Timbre and texture", "children": [{"id": "c1131209-d2c8-43e1-9c67-41497fe76872", "type": "concept", "title": "orchestral color"}, {"id": "031b099c-0448-4a9f-b93e-9e3dc8df68fd", "type": "concept", "title": "piano resonance"}, {"id": "093a0de7-7662-4836-9124-5bc05e2aa1e4", "type": "concept", "title": "textural layers"}], "description": "Students connect harmony to register, instrumentation, pedal, and resonance."}]}, {"id": "3d6c8325-c9a2-403c-bffa-d80898dc81f9", "type": "topic", "title": "Atonality and Free Atonality", "description": "Free atonality asks students to analyze music without assuming a tonal center or functional progression.", "children": [{"id": "8f0f74b8-c6a7-4f67-87b5-3331304bab6a", "type": "subtopic", "title": "Pitch organization without tonality", "children": [{"id": "448d7be0-8915-45cd-ae63-48a3f5c5d812", "type": "concept", "title": "interval cells"}, {"id": "873d8157-6e54-487e-bc5c-25b38e63770b", "type": "concept", "title": "motivic saturation"}, {"id": "7fa73591-7e10-4a1c-82df-8c8dce1e421e", "type": "concept", "title": "registral design"}], "description": "Students learn how composers create coherence through motives, intervals, and registers."}, {"id": "5e575dd6-ad74-4063-b240-1e4d68ca5cad", "type": "subtopic", "title": "Contour and gesture", "children": [{"id": "7961ba84-6cd2-4401-a8a9-52d9f204630a", "type": "concept", "title": "gestural analysis"}, {"id": "7e58d4ad-4ebc-4f17-8026-6c3c0e9f8720", "type": "concept", "title": "contour"}, {"id": "f842ef6f-9ecb-4ccb-ac8f-6721d00bcac3", "type": "concept", "title": "density"}], "description": "The class treats shape, attack, rhythm, and texture as structural features."}, {"id": "1614da30-b266-4f8a-b602-a5db6e7de8fa", "type": "subtopic", "title": "Analytical vocabulary", "children": [{"id": "9f389fea-131b-4411-b8dd-286b5b60abf8", "type": "concept", "title": "pitch-class language"}, {"id": "3fa30db0-053d-44b4-b5c8-20af1c276656", "type": "concept", "title": "interval vectors preview"}, {"id": "65f22167-6aae-459b-ae38-d9099dd8f34d", "type": "concept", "title": "segmentation"}], "description": "Students practice precise description for music that resists Roman-numeral analysis."}]}, {"id": "5ce85b67-c68b-4e69-8e5e-2bd15c3693cf", "type": "topic", "title": "Twelve-Tone Technique", "description": "Twelve-tone technique introduces a rigorous compositional system for organizing all twelve pitch classes.", "children": [{"id": "70f170d0-bac9-424a-a94d-87ac0a3f3ef2", "type": "subtopic", "title": "Tone rows", "children": [{"id": "3711d22c-1187-4554-871b-6212937c8921", "type": "concept", "title": "prime form"}, {"id": "618da9c3-d215-4344-bd9d-55ddeef87ace", "type": "concept", "title": "row ordering"}, {"id": "f3e5bbb8-4a42-40f5-a7bf-e4871780e01f", "type": "concept", "title": "aggregate"}], "description": "Students learn to identify and construct ordered pitch-class rows."}, {"id": "14cfd028-2b45-473f-8a27-1fdc8237fd7b", "type": "subtopic", "title": "Row operations", "children": [{"id": "f6247aae-bcbb-4a60-bcbd-40e16e4ecdc2", "type": "concept", "title": "inversion"}, {"id": "e70e0bd2-9eb6-4b12-85e7-fb9e2563ff10", "type": "concept", "title": "retrograde"}, {"id": "0d5cab5f-1124-4006-a8a3-201d54ea594b", "type": "concept", "title": "retrograde inversion"}], "description": "The unit covers the standard transformations used in serial composition."}, {"id": "404e79d6-1eba-4370-a040-a099905b0c8b", "type": "subtopic", "title": "Matrix and analysis", "children": [{"id": "824817bd-ee64-4b02-a5e3-406dc5dc5c71", "type": "concept", "title": "twelve-tone matrix"}, {"id": "0b2bc0f9-3f25-4c71-96b3-9485c4a67472", "type": "concept", "title": "row labels"}, {"id": "649d0683-959e-428d-b658-a3ee4c7e3ac4", "type": "concept", "title": "partitioning"}], "description": "Students build matrices and trace row forms through short works."}]}, {"id": "36c83826-effa-4de1-8fad-5a54acc5b574", "type": "topic", "title": "Set Theory Basics", "description": "Set theory gives students a compact language for comparing pitch collections in post-tonal music.", "children": [{"id": "421eecd4-1824-4862-9719-f720ce14aa34", "type": "subtopic", "title": "Pitch class and normal order", "children": [{"id": "96f4f80d-e7f4-453a-8c18-ae3c9f6eeb7f", "type": "concept", "title": "pitch-class integers"}, {"id": "cab33e59-1cb6-4a53-aa13-1303d2535428", "type": "concept", "title": "normal order"}, {"id": "b69faad5-bfe0-4abe-95a3-84ba60271d1a", "type": "concept", "title": "best normal order"}], "description": "Students learn the basic tools for unordered pitch-class collections."}, {"id": "e36ec5d8-